head.b:skin:
/* ==========================================================================
   RAJA PRIYA GROUP — APPLE MOBILE MENU & CLEAN THEME
   Full Mobile Navigation Drawer + 100% Suppression of Bloat Widgets
   ========================================================================== */

:root {
  --bg-main:          #07080a;
  --bg-surface:       #121318;
  --bg-glass:         rgba(18, 19, 24, 0.88);
  --bg-glass-card:    rgba(22, 23, 29, 0.72);

  --color-gold:       #d4af37;
  --color-gold-glow:  #f3e096;
  --color-gold-deep:  #8a6f23;

  --text-primary:     #f5f5f7;
  --text-secondary:   #86868b;
  --text-muted:       #6e6e73;

  --font-heading: 'Outfit', -apple-system, BlinkMacSystemFont, 'SF Pro Display', sans-serif;
  --font-body:    'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'SF Pro Text', sans-serif;

  --gradient-gold: linear-gradient(135deg, #c59b27 0%, #e6c867 50%, #f7e6a1 100%);
  --border-glass: 1px solid rgba(255, 255, 255, 0.08);
  --border-gold:  1px solid rgba(212, 175, 55, 0.35);

  --radius-sm:  8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --radius-xl: 28px;

  --shadow-apple: 0 20px 40px rgba(0, 0, 0, 0.6);
  --ease-apple: cubic-bezier(0.16, 1, 0.3, 1);
}

/* ---- PERMANENT SUPPRESSION OF ALL DEFAULT BLOGGER BLOAT WIDGETS ---- */
* { margin: 0; padding: 0; box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  background-color: var(--bg-main);
  color: var(--text-primary);
  font-family: var(--font-body);
  line-height: 1.65;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

/* Completely eradicate standard Blogger bloat cards (Header1, BlogSearch1, Attribution1, Profile1, etc.) */
#Header1, .widget.Header, div[id*="Header1"],
#BlogSearch1, .widget.BlogSearch, div[id*="BlogSearch"],
#Attribution1, .widget.Attribution, .attribution, div[id*="Attribution"],
#Profile1, .widget.Profile, .profile-datablock, div[id*="Profile"],
#BlogArchive1, .widget.BlogArchive, div[id*="BlogArchive"],
#PageList1, .widget.PageList, div[id*="PageList"],
#ReportAbuse1, div[id*="ReportAbuse"],
.widget-item-control, .item-control, .quickedit, .blog-feeds, .feed-links,
#FeaturedPost1, .FeaturedPost, div.FeaturedPost {
  display: none !important;
  visibility: hidden !important;
  height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  opacity: 0 !important;
  pointer-events: none !important;
}

a { text-decoration: none; color: inherit; transition: all 0.25s var(--ease-apple); }
a:hover { color: var(--color-gold-glow); }
img { max-width: 100%; height: auto; display: block; }
ul { list-style: none; }

/* Reading Progress Bar */
.reading-progress {
  position: fixed;
  top: 0;
  left: 0;
  height: 3px;
  background: var(--gradient-gold);
  z-index: 2000;
  width: 0%;
  transition: width 0.1s linear;
  box-shadow: 0 0 10px rgba(212, 175, 55, 0.8);
}

/* Container */
.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 32px;
}
@media (max-width: 640px) {
  .container { padding: 0 16px; }
}

/* ---- Apple Frosted Navbar & Mobile Hamburger ---- */
.apple-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: var(--bg-glass);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
  border-bottom: var(--border-glass);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 74px;
}
.brand-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-heading);
  font-size: 1.35rem;
  font-weight: 800;
  color: #ffffff;
  letter-spacing: -0.02em;
}
.brand-logo span {
  background: var(--gradient-gold);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  font-weight: 500;
}

/* Desktop Navigation Pills */
.nav-pills {
  display: flex;
  align-items: center;
  gap: 6px;
  background: rgba(255, 255, 255, 0.03);
  padding: 6px;
  border-radius: var(--radius-xl);
  border: var(--border-glass);
}
.nav-pill {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-secondary);
  padding: 8px 18px;
  border-radius: var(--radius-md);
  transition: all 0.25s var(--ease-apple);
}
.nav-pill:hover, .nav-pill.active {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.08);
}
.nav-pill.active {
  color: var(--color-gold);
  background: rgba(212, 175, 55, 0.12);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}
.btn-apple-gold {
  background: var(--gradient-gold);
  color: #07080a !important;
  font-weight: 700;
  font-size: 0.84rem;
  padding: 10px 20px;
  border-radius: var(--radius-xl);
  letter-spacing: 0.02em;
  box-shadow: 0 4px 16px rgba(212, 175, 55, 0.25);
  transition: transform 0.25s var(--ease-apple), box-shadow 0.25s var(--ease-apple);
  display: inline-block;
}
.btn-apple-gold:hover {
  transform: scale(1.03);
  box-shadow: 0 8px 24px rgba(212, 175, 55, 0.4);
}
.btn-apple-outline {
  background: rgba(255, 255, 255, 0.04);
  border: var(--border-glass);
  color: var(--text-primary) !important;
  font-weight: 600;
  font-size: 0.84rem;
  padding: 10px 18px;
  border-radius: var(--radius-xl);
  transition: all 0.25s var(--ease-apple);
  display: inline-block;
}
.btn-apple-outline:hover {
  background: rgba(255, 255, 255, 0.09);
  border-color: rgba(212, 175, 55, 0.4);
  color: var(--color-gold) !important;
}

/* ---- MOBILE HAMBURGER BUTTON & DRAWER MENU ---- */
.mobile-menu-btn {
  display: none;
  flex-direction: column;
  justify-content: space-between;
  width: 38px;
  height: 38px;
  background: rgba(255, 255, 255, 0.06);
  border: var(--border-gold);
  border-radius: var(--radius-sm);
  padding: 10px 8px;
  cursor: pointer;
  z-index: 1100;
}
.hamburger-bar {
  width: 100%;
  height: 2px;
  background-color: var(--color-gold);
  border-radius: 2px;
  transition: all 0.3s var(--ease-apple);
}

.mobile-drawer {
  display: none;
  position: fixed;
  top: 74px;
  left: 0;
  width: 100%;
  background: rgba(12, 13, 17, 0.96);
  backdrop-filter: blur(28px);
  -webkit-backdrop-filter: blur(28px);
  border-bottom: var(--border-gold);
  padding: 24px 20px;
  box-shadow: 0 20px 40px rgba(0,0,0,0.8);
  z-index: 1050;
  transform: translateY(-10px);
  opacity: 0;
  pointer-events: none;
  transition: all 0.3s var(--ease-apple);
}
.mobile-drawer.open {
  display: block;
  transform: translateY(0);
  opacity: 1;
  pointer-events: auto;
}
.mobile-nav-links {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.mobile-nav-links a {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text-primary);
  padding: 12px 16px;
  background: rgba(255, 255, 255, 0.03);
  border: var(--border-glass);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.mobile-nav-links a.active, .mobile-nav-links a:hover {
  color: var(--color-gold);
  background: rgba(212, 175, 55, 0.12);
  border-color: rgba(212, 175, 55, 0.4);
}

@media (max-width: 992px) {
  .nav-pills { display: none; }
  .btn-apple-outline { display: none; }
  .mobile-menu-btn { display: flex; }
}

/* ---- Apple Hero Banner ---- */
.hero-apple {
  position: relative;
  padding: 56px 0 32px;
  text-align: center;
  overflow: hidden;
}
.hero-apple::before {
  content: '';
  position: absolute;
  top: -150px;
  left: 50%;
  transform: translateX(-50%);
  width: 600px;
  height: 400px;
  background: radial-gradient(circle, rgba(212, 175, 55, 0.15) 0%, rgba(7, 8, 10, 0) 70%);
  pointer-events: none;
}
.badge-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(212, 175, 55, 0.1);
  border: var(--border-gold);
  padding: 6px 16px;
  border-radius: var(--radius-xl);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-gold);
  margin-bottom: 18px;
}
.badge-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-gold);
  box-shadow: 0 0 8px var(--color-gold);
}
.hero-title {
  font-family: var(--font-heading);
  font-size: clamp(2.1rem, 5vw, 3.8rem);
  font-weight: 800;
  line-height: 1.15;
  color: #ffffff;
  letter-spacing: -0.03em;
  margin-bottom: 16px;
}
.hero-title span {
  background: var(--gradient-gold);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}
.hero-sub {
  color: var(--text-secondary);
  font-size: 1.08rem;
  max-width: 650px;
  margin: 0 auto;
  line-height: 1.6;
}

/* ---- GOOGLE ADSENSE SLOTS (Clean & Seamless) ---- */
.ad-slot-container {
  margin: 24px 0;
  text-align: center;
  width: 100%;
}

/* ---- MAIN BLOG-FIRST LAYOUT ---- */
.layout-wrapper {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 48px;
  padding: 48px 0 80px;
}
@media (max-width: 992px) {
  .layout-wrapper { grid-template-columns: 1fr; gap: 40px; }
}

/* Post Cards Grid */
.posts-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(310px, 1fr));
  gap: 28px;
}
@media (max-width: 640px) {
  .posts-grid { grid-template-columns: 1fr; }
}

.post-card {
  background: var(--bg-glass-card);
  backdrop-filter: blur(16px);
  border: var(--border-glass);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: 0 10px 30px rgba(0,0,0,0.3);
  transition: transform 0.35s var(--ease-apple), border-color 0.35s var(--ease-apple), box-shadow 0.35s var(--ease-apple);
}
.post-card:hover {
  transform: translateY(-6px);
  border-color: rgba(212, 175, 55, 0.4);
  box-shadow: var(--shadow-apple);
}
.card-img-wrap {
  position: relative;
  width: 100%;
  height: 210px;
  overflow: hidden;
  background: #181920;
}
.post-card-thumb {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s var(--ease-apple);
}
.post-card:hover .post-card-thumb {
  transform: scale(1.06);
}
.card-tag {
  position: absolute;
  top: 14px;
  left: 14px;
  background: rgba(7, 8, 10, 0.82);
  backdrop-filter: blur(10px);
  border: var(--border-gold);
  color: var(--color-gold);
  font-size: 0.72rem;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: var(--radius-xl);
  text-transform: uppercase;
}

.post-card-body {
  padding: 24px;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}
.post-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-bottom: 10px;
}
.post-title {
  font-family: var(--font-heading);
  font-size: 1.3rem;
  font-weight: 700;
  line-height: 1.3;
  color: #ffffff;
  margin-bottom: 12px;
}
.post-snippet {
  color: var(--text-secondary);
  font-size: 0.92rem;
  line-height: 1.6;
  margin-bottom: 20px;
  flex-grow: 1;
}
.post-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 16px;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  font-size: 0.84rem;
  color: var(--text-muted);
}
.read-story {
  color: var(--color-gold);
  font-weight: 700;
  font-size: 0.85rem;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

/* Single Article View */
.single-post {
  background: var(--bg-glass-card);
  backdrop-filter: blur(20px);
  border: var(--border-glass);
  border-radius: var(--radius-lg);
  padding: 56px 48px;
  box-shadow: var(--shadow-apple);
  width: 100%;
}
@media (max-width: 640px) {
  .single-post { padding: 24px 18px; }
}
.single-post-title {
  font-family: var(--font-heading);
  font-size: clamp(2.4rem, 5.5vw, 3.6rem);
  font-weight: 800;
  line-height: 1.2;
  color: #ffffff;
  margin-bottom: 20px;
}
.single-post-meta {
  display: flex;
  align-items: center;
  gap: 16px;
  font-size: 0.95rem;
  color: var(--color-gold);
  margin-bottom: 36px;
  padding-bottom: 24px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}
.single-post-content {
  font-size: 1.22rem;
  line-height: 1.9;
  color: #e3e3e8;
}
.single-post-content p { margin-bottom: 28px; }
.single-post-content img { width: 100%; max-width: 100%; height: auto; border-radius: 16px; margin: 24px 0; display: block; }
.single-post-content h2 { font-size: 2.2rem; color: var(--color-gold); margin: 40px 0 20px; font-family: var(--font-heading); }
.single-post-content h3 { font-size: 1.7rem; color: #ffffff; margin: 32px 0 16px; font-family: var(--font-heading); }

/* Share Widget */
.share-box {
  margin-top: 40px;
  padding-top: 24px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px;
}
.share-label { font-weight: 700; color: #ffffff; font-size: 0.9rem; }
.share-links { display: flex; flex-wrap: wrap; gap: 10px; }
.share-btn {
  background: rgba(255, 255, 255, 0.05);
  border: var(--border-glass);
  color: #ffffff;
  padding: 8px 16px;
  border-radius: var(--radius-xl);
  font-size: 0.82rem;
  font-weight: 600;
}
.share-btn:hover {
  background: rgba(212, 175, 55, 0.15);
  border-color: var(--color-gold);
  color: var(--color-gold);
}

/* ---- 4 CORE SERVICES SHOWCASE (RELOCATED BELOW BLOG POSTS) ---- */
.services-section {
  padding: 64px 0;
  border-top: var(--border-glass);
  border-bottom: var(--border-glass);
}
.section-head {
  text-align: center;
  margin-bottom: 40px;
}
.section-eyebrow {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--color-gold);
  margin-bottom: 8px;
  display: block;
}
.section-title {
  font-family: var(--font-heading);
  font-size: clamp(1.8rem, 3.5vw, 2.6rem);
  font-weight: 700;
  color: #ffffff;
}

.services-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
@media (max-width: 1100px) {
  .services-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 640px) {
  .services-grid { grid-template-columns: 1fr; }
}

.service-card {
  background: var(--bg-glass-card);
  backdrop-filter: blur(16px);
  border: var(--border-glass);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  display: flex;
  flex-direction: column;
  transition: transform 0.35s var(--ease-apple), border-color 0.35s var(--ease-apple), box-shadow 0.35s var(--ease-apple);
}
.service-card:hover {
  transform: translateY(-6px);
  border-color: rgba(212, 175, 55, 0.45);
  box-shadow: var(--shadow-apple);
}
.service-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: rgba(212, 175, 55, 0.1);
  border: var(--border-gold);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-gold);
  margin-bottom: 20px;
}
.service-title {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  color: #ffffff;
  margin-bottom: 18px;
}
.service-list {
  margin-bottom: 24px;
  flex-grow: 1;
}
.service-list li {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  gap: 10px;
  line-height: 1.4;
}
.bullet-icon {
  color: var(--color-gold);
  font-weight: 700;
  font-size: 0.85rem;
  flex-shrink: 0;
}
.service-link {
  color: var(--color-gold);
  font-weight: 700;
  font-size: 0.85rem;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: auto;
}

/* ---- INTERACTIVE FAQ ACCORDION (RELOCATED BELOW SERVICES) ---- */
.faq-section {
  padding: 64px 0;
  border-bottom: var(--border-glass);
}
.faq-container {
  max-width: 820px;
  margin: 0 auto;
}
.faq-item {
  background: var(--bg-glass-card);
  border: var(--border-glass);
  border-radius: var(--radius-md);
  margin-bottom: 16px;
  overflow: hidden;
}
.faq-question {
  padding: 20px 24px;
  font-family: var(--font-heading);
  font-size: 1.05rem;
  font-weight: 700;
  color: #ffffff;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.faq-question:hover { color: var(--color-gold); }
.faq-answer {
  padding: 0 24px 20px;
  font-size: 0.94rem;
  color: var(--text-secondary);
  line-height: 1.6;
  display: none;
}
.faq-item.active .faq-answer { display: block; }
.faq-item.active .faq-toggle { transform: rotate(180deg); }

/* ---- APPLE SIDEBAR WIDGETS ---- */
.widget {
  background: var(--bg-glass-card);
  backdrop-filter: blur(16px);
  border: var(--border-glass);
  border-radius: var(--radius-lg);
  padding: 28px;
  margin-bottom: 28px;
}
.widget-title {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  font-weight: 700;
  color: #ffffff;
  margin-bottom: 20px;
  position: relative;
  padding-bottom: 10px;
}
.widget-title::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 44px;
  height: 3px;
  border-radius: 3px;
  background: var(--gradient-gold);
}

/* Consultation CTA Widget */
.cta-widget {
  background: linear-gradient(135deg, rgba(22,23,29,0.95) 0%, rgba(12,13,17,0.95) 100%);
  border: var(--border-gold);
  text-align: center;
  box-shadow: 0 12px 30px rgba(0,0,0,0.4);
}
.cta-widget h4 {
  font-family: var(--font-heading);
  font-size: 1.3rem;
  font-weight: 700;
  color: #ffffff;
  margin-bottom: 8px;
}
.cta-widget p {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-bottom: 20px;
}

/* Newsletter Subscription Box */
.newsletter-widget {
  border: var(--border-gold);
  background: rgba(212, 175, 55, 0.04);
}
.newsletter-input {
  width: 100%;
  background: rgba(255, 255, 255, 0.05);
  border: var(--border-glass);
  color: #ffffff;
  padding: 12px 16px;
  border-radius: var(--radius-xl);
  font-family: inherit;
  font-size: 0.88rem;
  margin-bottom: 12px;
}

/* Trending Topics Tag Cloud */
.tag-cloud {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.tag-pill {
  background: rgba(255, 255, 255, 0.05);
  border: var(--border-glass);
  color: var(--text-secondary);
  font-size: 0.8rem;
  font-weight: 600;
  padding: 6px 14px;
  border-radius: var(--radius-xl);
  transition: all 0.25s var(--ease-apple);
}
.tag-pill:hover {
  color: var(--color-gold);
  border-color: var(--color-gold);
  background: rgba(212, 175, 55, 0.1);
}

.quick-services-widget li {
  margin-bottom: 10px;
  padding-bottom: 10px;
  border-bottom: 1px solid rgba(255,255,255,0.05);
}
.quick-services-widget a {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.quick-services-widget a:hover {
  color: var(--color-gold);
}

.search-form {
  display: flex;
  gap: 8px;
}
.search-input {
  flex-grow: 1;
  background: rgba(255, 255, 255, 0.05);
  border: var(--border-glass);
  color: #ffffff;
  padding: 10px 16px;
  border-radius: var(--radius-xl);
  font-family: inherit;
  font-size: 0.9rem;
}

/* FLOATING CONSULTATION BUTTON */
.floating-wa-btn {
  position: fixed;
  bottom: 24px;
  right: 24px;
  z-index: 1500;
  background: rgba(18, 19, 24, 0.92);
  backdrop-filter: blur(16px);
  border: var(--border-gold);
  color: #ffffff;
  padding: 10px 20px;
  border-radius: var(--radius-xl);
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.85rem;
  font-weight: 700;
  box-shadow: 0 10px 30px rgba(0,0,0,0.5);
  transition: transform 0.25s var(--ease-apple);
}
.floating-wa-btn:hover {
  transform: translateY(-3px) scale(1.02);
  color: var(--color-gold);
}
.online-pulse {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #25d366;
  box-shadow: 0 0 10px #25d366;
}

/* Pager */
.blog-pager {
  display: flex;
  justify-content: space-between;
  margin-top: 48px;
}
.blog-pager a {
  background: var(--bg-glass-card);
  border: var(--border-gold);
  color: var(--color-gold);
  padding: 12px 24px;
  border-radius: var(--radius-xl);
  font-weight: 700;
  font-size: 0.88rem;
}

/* ---- APPLE FOOTER ---- */
.apple-footer {
  background: #040405;
  border-top: var(--border-glass);
  padding: 72px 0 36px;
  color: var(--text-secondary);
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 48px;
}
@media (max-width: 900px) {
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
}
@media (max-width: 600px) {
  .footer-grid { grid-template-columns: 1fr; gap: 28px; }
}
.footer-brand {
  font-family: var(--font-heading);
  font-size: 1.4rem;
  font-weight: 800;
  color: #ffffff;
  margin-bottom: 14px;
}
.footer-brand span {
  background: var(--gradient-gold);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}
.footer-title {
  font-family: var(--font-heading);
  color: #ffffff;
  font-weight: 700;
  font-size: 0.95rem;
  margin-bottom: 18px;
}
.footer-links li { margin-bottom: 10px; }
.footer-links a {
  font-size: 0.88rem;
  color: var(--text-secondary);
}
.footer-links a:hover { color: var(--color-gold); }

.footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  padding-top: 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.84rem;
  flex-wrap: wrap;
  gap: 16px;
}
.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(255, 255, 255, 0.04);
  border: var(--border-glass);
  padding: 6px 14px;
  border-radius: var(--radius-xl);
  color: var(--text-primary);
}
.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #34c759;
  box-shadow: 0 0 10px #34c759;
}

head.script:
// Reading Progress Bar
window.addEventListener('scroll', function() {
  var winScroll = document.body.scrollTop || document.documentElement.scrollTop;
  var height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
  var scrolled = (winScroll / height) * 100;
  var bar = document.getElementById('readingProgress');
  if (bar) { bar.style.width = scrolled + '%'; }
});

// FAQ Accordion Toggle
function toggleFaq(element) {
  var item = element.parentElement;
  item.classList.toggle('active');
}

// Mobile Navigation Drawer Toggle
function toggleMobileMenu() {
  var drawer = document.getElementById('mobileDrawer');
  var btn = document.getElementById('mobileMenuBtn');
  if (drawer) { drawer.classList.toggle('open'); }
  if (btn) { btn.classList.toggle('active'); }
}
